import re

_ROMAN_RE = re.compile(r'^M+(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$')
_VALUES = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}

def solve(s):
    """Convert a valid Roman numeral (I V X L C D M, subtractive notation)
    to its integer value. Raise ValueError for empty or invalid input."""
    if not isinstance(s, str) or not _ROMAN_RE.match(s.strip()):
        raise ValueError("invalid Roman numeral: %r" % (s,))
    total = 0
    prev = 0
    for ch in reversed(s.strip()):
        v = _VALUES[ch]
        if v < prev:
            total -= v
        else:
            total += v
            prev = v
    return total

