def solve(matrix):
    n = len(matrix)
    if n == 0:
        return 1
    # Bareiss fraction-free elimination: exact integer arithmetic throughout.
    M = [list(row) for row in matrix]
    sign = 1
    prev = 1
    for k in range(n - 1):
        if M[k][k] == 0:
            pivot_row = None
            for i in range(k + 1, n):
                if M[i][k] != 0:
                    pivot_row = i
                    break
            if pivot_row is None:
                return 0  # entire column below pivot is zero -> singular
            M[k], M[pivot_row] = M[pivot_row], M[k]
            sign = -sign
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                M[i][j] = (M[i][j] * M[k][k] - M[i][k] * M[k][j]) // prev
            M[i][k] = 0
        prev = M[k][k]
    return sign * M[n - 1][n - 1]

