    if s is None or s == '':
        return ''
    # Manacher's algorithm, O(n). Ties broken by earliest start: centers are
    # scanned left to right and updates require strictly greater length.
    t = '#' + '#'.join(s) + '#'
    n = len(t)
    p = [0] * n
    center = right = 0
    best_len = 0
    best_start = 0
    for i in range(n):
        if i < right:
            p[i] = min(right - i, p[2 * center - i])
        while i - p[i] - 1 >= 0 and i + p[i] + 1 < n and t[i - p[i] - 1] == t[i + p[i] + 1]:
            p[i] += 1
        if i + p[i] > right:
            center, right = i, i + p[i]
        if p[i] > best_len:
            best_len = p[i]
            best_start = (i - p[i]) // 2
    return s[best_start:best_start + best_len]
