def solve(*args, **kwargs):
    """Validate an IPv4 address.
    Accepts the address either as the first positional argument or as a
    keyword argument named ``s`` or ``ip``. Any extra arguments are ignored.
    Returns ``True`` if the string is a valid dotted IPv4 address according to
    the specification: exactly four decimal numbers, each between 0 and 255,
    without leading zeros (except the solitary ``0``). Otherwise ``False``.
    """
    # Extract the input string.
    if args:
        s = args[0]
    else:
        s = kwargs.get('s', kwargs.get('ip', ''))
    # Must be a string.
