def solve(intervals):
    """Merge overlapping intervals.
    Each interval is a list or tuple of two numbers. If an interval has its
    start greater than its end, the endpoints are swapped. Intervals that touch
    (end == next start) are merged as well, matching the usual definition.
    Returns a list of merged intervals as lists ordered by start.
    """
    if not intervals:
        return []
    # Normalize intervals to [start, end] with start <= end
    norm = []
    for iv in intervals:
        if len(iv) != 2:
            continue  # ignore malformed intervals
        a, b = iv[0], iv[1]
        if a <= b:
            norm.append([a, b])
        else:
            norm.append([b, a])
    if not norm:
        return []
    # Sort by start
    norm.sort(key=lambda x: x[0])
    merged = [norm[0][:]]
    for start, end in norm[1:]:
        last = merged[-1]
        if start <= last[1]:  # overlapping or touching
            # extend the previous interval's end if needed
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end])
    return merged

