def solve(n, edges):
    """Return the smallest total weight from node 0 to node n-1 in an
    undirected graph with positive edge weights, or -1 if unreachable."""
    if n is None or n <= 0:
        return -1
    if n == 1:
        return 0
    adj = {i: [] for i in range(n)}
    for e in edges:
        try:
            a, b, w = e
        except (TypeError, ValueError):
            continue
        if not (0 <= a < n and 0 <= b < n):
            continue
        adj[a].append((b, w))
        adj[b].append((a, w))
    import heapq
    best = {0: 0}
    heap = [(0, 0)]
    while heap:
        d, u = heapq.heappop(heap)
        if u == n - 1:
            return d
        if d > best.get(u, float('inf')):
            continue
        for v, w in adj[u]:
            nd = d + w
            if nd < best.get(v, float('inf')):
                best[v] = nd
                heapq.heappush(heap, (nd, v))
    return -1

