def solve(grid):
    """Count the islands (connected groups of 1s, 4-directional) in a
    binary grid. Empty grid counts as 0 islands."""
    if not grid or not grid[0]:
        return 0
    n = len(grid)
    seen = [[False] * len(grid[r]) for r in range(n)]
    count = 0
    for r in range(n):
        m = len(grid[r])
        for c in range(m):
            if (grid[r][c] == 1 or grid[r][c] == '1') and not seen[r][c]:
                count += 1
                stack = [(r, c)]
                seen[r][c] = True
                while stack:
                    i, j = stack.pop()
                    for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        ni, nj = i + di, j + dj
                        if (0 <= ni < n and 0 <= nj < len(grid[ni])
                                and (grid[ni][nj] == 1 or grid[ni][nj] == '1')
                                and not seen[ni][nj]):
                            seen[ni][nj] = True
                            stack.append((ni, nj))
    return count

