def solve(s):
    if not isinstance(s, str):
        return False
    s = s.strip()
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part or not part.isdigit():
            return False
        if len(part) > 1 and part[0] == '0':
            return False
        val = int(part)
        if val < 0 or val > 255:
            return False
    return True
